import{_ as t,a,c as i,ac as n}from"./chunks/framework.BSuaGltH.js";const p=JSON.parse('{"title":"第四册：流利英语 · Lesson 23 Bird flight","description":"学习 现在分词状语与逻辑主语，配有原创例句、重点词汇和带解析的自测。","frontmatter":{"title":"第四册：流利英语 · Lesson 23 Bird flight","description":"学习 现在分词状语与逻辑主语，配有原创例句、重点词汇和带解析的自测。","showdocs":{"topics":[{"id":"english","title":"英语","link":"/topics/english/"}],"kind":"路线与能力起点","scope":"general","audience":"general","group":"学习与记录","seriesTitle":"新概念英语经典版第4册课时","summary":"学习 现在分词状语与逻辑主语，配有原创例句、重点词汇和带解析的自测。","status":"active","related":[{"title":"程序员英语 08：一次完整的阅读与协作实战","link":"/life/english/programmer/practice","kind":"读写与对话练习","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语","link":"/life/english/new-concept/book-2/unit-01/vocabulary","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语 · 第17–24课","link":"/life/english/new-concept/book-2/unit-01/vocabulary-part-02","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语 · 字母索引与第1–16课","link":"/life/english/new-concept/book-2/unit-01/vocabulary-part-01","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 复习与自测","link":"/life/english/new-concept/book-2/unit-01/review","kind":"读写与对话练习","scope":"general","audience":"general"}],"prev":{"text":"第四册：流利英语 · Lesson 22 Knowledge and progress","link":"/life/english/new-concept/book-4/unit-03/lesson-022"},"next":{"text":"第四册：流利英语 · Lesson 24 Beauty","link":"/life/english/new-concept/book-4/unit-03/lesson-024"}},"layout":"ReadingPage","sidebar":false,"aside":false,"prev":{"text":"第四册：流利英语 · Lesson 22 Knowledge and progress","link":"/life/english/new-concept/book-4/unit-03/lesson-022"},"next":{"text":"第四册：流利英语 · Lesson 24 Beauty","link":"/life/english/new-concept/book-4/unit-03/lesson-024"}},"headers":[],"relativePath":"life/english/new-concept/book-4/unit-03/lesson-023.md","filePath":"life/english/new-concept/book-4/unit-03/lesson-023.md"}'),l={name:"life/english/new-concept/book-4/unit-03/lesson-023.md"};function o(r,e,s,d,h,c){return a(),i("div",null,[...e[0]||(e[0]=[n('<h1 id="第四册-流利英语-·-lesson-23-bird-flight" tabindex="-1">第四册：流利英语 · Lesson 23 Bird flight <a class="header-anchor" href="#第四册-流利英语-·-lesson-23-bird-flight" aria-label="Permalink to &quot;第四册：流利英语 · Lesson 23 Bird flight&quot;">​</a></h1><p><a href="/life/english/new-concept/overview">系列目录</a> · <a href="/life/english/new-concept/book-4/contents">本册目录</a> · <a href="/life/english/new-concept/book-4/unit-03/overview">单元 3</a></p><h2 id="学习目标与内容导读" tabindex="-1">学习目标与内容导读 <a class="header-anchor" href="#学习目标与内容导读" aria-label="Permalink to &quot;学习目标与内容导读&quot;">​</a></h2><p>以鸟类飞行的观察为线索，学习描述同时发生的动作及其功能。区分拍翼、滑翔等可见行为和关于能量或空气作用的解释，避免用单一描述概括所有鸟类。重点训练分词状语的逻辑主语，让句子既紧凑又不会把动作错误地归给无生命物体。</p><p>本课以主题阅读带动语言分析，学习重点如下。</p><h2 id="单词与搭配" tabindex="-1">单词与搭配 <a class="header-anchor" href="#单词与搭配" aria-label="Permalink to &quot;单词与搭配&quot;">​</a></h2><table tabindex="0"><thead><tr><th>单词</th><th>音标</th><th>词性</th><th>本页义项</th><th>搭配</th></tr></thead><tbody><tr><td>wing</td><td>/wɪŋ/</td><td>n.</td><td>翅膀</td><td>spread its wings</td></tr><tr><td>glide</td><td>/ɡlaɪd/</td><td>v.</td><td>滑翔</td><td>glide over water</td></tr><tr><td>lift</td><td>/lɪft/</td><td>n.</td><td>升力</td><td>generate lift</td></tr><tr><td>current</td><td>/ˈkʌrənt/</td><td>n.</td><td>气流；水流</td><td>a rising air current</td></tr></tbody></table><h2 id="短语与句型" tabindex="-1">短语与句型 <a class="header-anchor" href="#短语与句型" aria-label="Permalink to &quot;短语与句型&quot;">​</a></h2><ul><li>take advantage of — 利用有利条件</li><li>change direction — 改变方向</li></ul><h2 id="语法讲解-现在分词状语与逻辑主语" tabindex="-1">语法讲解：现在分词状语与逻辑主语 <a class="header-anchor" href="#语法讲解-现在分词状语与逻辑主语" aria-label="Permalink to &quot;语法讲解：现在分词状语与逻辑主语&quot;">​</a></h2><p>现在分词短语可表示同时动作、方式或伴随，通常与主句主语共享动作执行者。Gliding above the lake, the bird changed direction. 中 gliding 的执行者是 bird。若写 Gliding above the lake, the wind grew stronger，就错误地让 wind 执行滑翔动作，形成悬垂修饰。分词不独立标明时态，时间关系由主句和语境确定；需要明确不同主语时改用完整从句。</p><h2 id="原创例句与结构分析" tabindex="-1">原创例句与结构分析 <a class="header-anchor" href="#原创例句与结构分析" aria-label="Permalink to &quot;原创例句与结构分析&quot;">​</a></h2><blockquote><p>Gliding above the field, the bird turned towards the hills.</p></blockquote><p>鸟在田野上方滑翔着，转向了群山。</p><p>Gliding… 为伴随分词状语，逻辑主语为 the bird，与 turned 的主语一致。</p><h2 id="易错辨析" tabindex="-1">易错辨析 <a class="header-anchor" href="#易错辨析" aria-label="Permalink to &quot;易错辨析&quot;">​</a></h2><p>Watching the bird, its wings looked wide 错把 wings 当观察者；可改为 As I watched the bird, its wings looked wide。</p><h2 id="听说训练" tabindex="-1">听说训练 <a class="header-anchor" href="#听说训练" aria-label="Permalink to &quot;听说训练&quot;">​</a></h2><p>分词短语后停一小拍，主句重读 bird；回听时确认没有因停顿而丢失共同主语。</p><h2 id="读写训练" tabindex="-1">读写训练 <a class="header-anchor" href="#读写训练" aria-label="Permalink to &quot;读写训练&quot;">​</a></h2><h3 id="阅读材料-本站原创" tabindex="-1">阅读材料（本站原创） <a class="header-anchor" href="#阅读材料-本站原创" aria-label="Permalink to &quot;阅读材料（本站原创）&quot;">​</a></h3><p>Circling above the trees, a large bird gradually gained height. It then moved across the valley without flapping. From the ground, I could not identify the species with confidence.</p><h3 id="表达任务" tabindex="-1">表达任务 <a class="header-anchor" href="#表达任务" aria-label="Permalink to &quot;表达任务&quot;">​</a></h3><p>用三句记录一次鸟类观察，含分词状语、动作变化和观察限制。</p><details class="details custom-block"><summary>写作提示与点评</summary><p>动作描述具体，最后将物种判断与观察事实分开。</p></details><h2 id="课后自测" tabindex="-1">课后自测 <a class="header-anchor" href="#课后自测" aria-label="Permalink to &quot;课后自测&quot;">​</a></h2><h3 id="练习-1" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1" aria-label="Permalink to &quot;练习 1&quot;">​</a></h3><p>示例中谁在 gliding？</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> the bird</p><p><strong>解析：</strong> 分词状语与主句共享主语。</p></details><h3 id="练习-2" tabindex="-1">练习 2 <a class="header-anchor" href="#练习-2" aria-label="Permalink to &quot;练习 2&quot;">​</a></h3><p>改错：Walking beside the lake, the bird caught my attention.（表达“我散步”）</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> While I was walking beside the lake, the bird caught my attention.</p><p><strong>解析：</strong> 完整从句明确 walking 的主语是 I。</p></details><h3 id="练习-3" tabindex="-1">练习 3 <a class="header-anchor" href="#练习-3" aria-label="Permalink to &quot;练习 3&quot;">​</a></h3><p>将 The bird circled slowly and gained height. 用分词开头改写。</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> Circling slowly, the bird gained height.</p><p><strong>解析：</strong> 两个动作共享 bird，可用分词状语。</p></details><h2 id="复习导航" tabindex="-1">复习导航 <a class="header-anchor" href="#复习导航" aria-label="Permalink to &quot;复习导航&quot;">​</a></h2><p>本课重点：现在分词状语与逻辑主语。复习时先遮住答案重做自测，再将示范中的人物、时间或条件改为自己的情境；解释改动后哪些词需要变化。</p><p><a href="/life/english/new-concept/book-4/unit-03/grammar">单元语法</a> · <a href="/life/english/new-concept/book-4/unit-03/vocabulary">单元单词</a> · <a href="/life/english/new-concept/book-4/unit-03/review">单元自测</a></p><p><a href="/life/english/new-concept/book-4/unit-03/lesson-022">上一课</a> · <a href="/life/english/new-concept/book-4/unit-03/overview">单元目录</a> · <a href="/life/english/new-concept/book-4/unit-03/lesson-024">下一课</a></p><hr><p>本站原创学习伴读：保留经典版课号和课名，讲解、例句与练习独立编写。重点词汇用于本页学习，不等同于教材全部生词表；教材课文、完整译文、原题与录音请配合自己的正版教材使用。</p>',41)])])}const u=t(l,[["render",o]]);export{p as __pageData,u as default};
